{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Bupropion, a high-transfer reference, showed rapid BBB equilibration with Kp,uu 1.9 in rat microdialysis, indicating net brain uptake rather than efflux-limited exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Hydroxybupropion also achieved Kp,uu 1.7 in rat microdialysis, confirming meaningful unbound brain exposure for a closely transferable molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Ketamine in humans reached a CSF:plasma ratio of 0.917, directly demonstrating CNS access after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "(S)-Ketamine in rats maintained brain:plasma ratios of 5.7-12.3 over 10-60 minutes, showing robust and sustained brain uptake.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Clofoctol, a lipophilic aromatic compound, produced measurable mouse brain concentrations after i.v. dosing, supporting CNS access for aromatic lipophilic chemotypes.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer in vivo measurements consistently demonstrate meaningful CNS access for structurally applicable molecules. The query's moderate passive properties and acidic imide are not sufficient to overturn this consistent experimental pattern, so the prediction is pass.",
  "evidence_gaps": [
    "No direct Kp,uu or CSF measurement for the exact query molecule.",
    "No explicit P-gp/BCRP efflux data for the maleimide scaffold.",
    "Acidic imide ionization at pH 7.4 may reduce passive permeability relative to the basic amine reference compounds."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

